insert into public.reviews (id, name, text, rating, area, created_at) values ('00000000-0000-4000-8005-000000000001', 'Tolu A.', 'Bought a UK-used 14 Pro. The condition report matched exactly, battery at 89% like they said. No stories.', 5, 'Lekki', now() - interval '0 minutes');
insert into public.reviews (id, name, text, rating, area, created_at) values ('00000000-0000-4000-8005-000000000002', 'Chinedu O.', 'Swapped my 12 Pro Max for a 15 Pro Max. The estimate online was within ₦20k of the final offer.', 5, 'Ikeja', now() - interval '1 minutes');
insert into public.reviews (id, name, text, rating, area, created_at) values ('00000000-0000-4000-8005-000000000003', 'Funmi B.', 'Screen fixed the same afternoon. They showed me the old part and the new one before closing it up.', 5, 'Yaba', now() - interval '2 minutes');
insert into public.reviews (id, name, text, rating, area, created_at) values ('00000000-0000-4000-8005-000000000004', 'Ibrahim S.', 'Delivery took one extra day, but they kept me updated on WhatsApp the whole time. Phone was perfect.', 4, 'Surulere', now() - interval '3 minutes');
insert into public.reviews (id, name, text, rating, area, created_at) values ('00000000-0000-4000-8005-000000000005', 'Ada N.', 'First time buying a phone online in Lagos without fear. Sealed box, receipt, warranty card.', 5, 'Victoria Island', now() - interval '4 minutes');
insert into public.reviews (id, name, text, rating, area, created_at) values ('00000000-0000-4000-8005-000000000006', 'Kunle F.', 'Prices are fair and they don''t rush you. Ordered on WhatsApp at 9pm, phone arrived by noon.', 5, 'Ajah', now() - interval '5 minutes');
insert into public.settings (id, whatsapp_number, store_address, opening_hours, delivery_note, instagram_handle) values (1, '2349130928293', 'Computer Village, Ikeja, Lagos (placeholder)', 'Mon–Sat 9am–7pm', 'Same-day delivery in Lagos. Nationwide delivery in 1–3 days.', 'guccigadgets');
